macro_rules! deps {
    () => {
        StreamExt!();
    };
}

macro_rules! StreamMap {
    () => {
        deps!();
        # [doc = " Combine many streams into one, indexing each source stream with a unique"] # [doc = " key."] # [doc = ""] # [doc = " `StreamMap` is similar to [`StreamExt::merge`] in that it combines source"] # [doc = " streams into a single merged stream that yields values in the order that"] # [doc = " they arrive from the source streams. However, `StreamMap` has a lot more"] # [doc = " flexibility in usage patterns."] # [doc = ""] # [doc = " `StreamMap` can:"] # [doc = ""] # [doc = " * Merge an arbitrary number of streams."] # [doc = " * Track which source stream the value was received from."] # [doc = " * Handle inserting and removing streams from the set of managed streams at"] # [doc = "   any point during iteration."] # [doc = ""] # [doc = " All source streams held by `StreamMap` are indexed using a key. This key is"] # [doc = " included with the value when a source stream yields a value. The key is also"] # [doc = " used to remove the stream from the `StreamMap` before the stream has"] # [doc = " completed streaming."] # [doc = ""] # [doc = " # `Unpin`"] # [doc = ""] # [doc = " Because the `StreamMap` API moves streams during runtime, both streams and"] # [doc = " keys must be `Unpin`. In order to insert a `!Unpin` stream into a"] # [doc = " `StreamMap`, use [`pin!`] to pin the stream to the stack or [`Box::pin`] to"] # [doc = " pin the stream in the heap."] # [doc = ""] # [doc = " # Implementation"] # [doc = ""] # [doc = " `StreamMap` is backed by a `Vec<(K, V)>`. There is no guarantee that this"] # [doc = " internal implementation detail will persist in future versions, but it is"] # [doc = " important to know the runtime implications. In general, `StreamMap` works"] # [doc = " best with a \"smallish\" number of streams as all entries are scanned on"] # [doc = " insert, remove, and polling. In cases where a large number of streams need"] # [doc = " to be merged, it may be advisable to use tasks sending values on a shared"] # [doc = " [`mpsc`] channel."] # [doc = ""] # [doc = " # Notes"] # [doc = ""] # [doc = " `StreamMap` removes finished streams automatically, without alerting the user."] # [doc = " In some scenarios, the caller would want to know on closed streams."] # [doc = " To do this, use [`StreamNotifyClose`] as a wrapper to your stream."] # [doc = " It will return None when the stream is closed."] # [doc = ""] # [doc = " [`StreamExt::merge`]: crate::StreamExt::merge"] # [doc = " [`mpsc`]: https://docs.rs/tokio/1.0/tokio/sync/mpsc/index.html"] # [doc = " [`pin!`]: https://docs.rs/tokio/1.0/tokio/macro.pin.html"] # [doc = " [`Box::pin`]: std::boxed::Box::pin"] # [doc = " [`StreamNotifyClose`]: crate::StreamNotifyClose"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Merging two streams, then remove them after receiving the first value"] # [doc = ""] # [doc = " ```"] # [doc = " use tokio_stream::{StreamExt, StreamMap, Stream};"] # [doc = " use tokio::sync::mpsc;"] # [doc = " use std::pin::Pin;"] # [doc = ""] # [doc = " # #[tokio::main(flavor = \"current_thread\")]"] # [doc = " # async fn main() {"] # [doc = " let (tx1, mut rx1) = mpsc::channel::<usize>(10);"] # [doc = " let (tx2, mut rx2) = mpsc::channel::<usize>(10);"] # [doc = ""] # [doc = " // Convert the channels to a `Stream`."] # [doc = " let rx1 = Box::pin(async_stream::stream! {"] # [doc = "     while let Some(item) = rx1.recv().await {"] # [doc = "         yield item;"] # [doc = "     }"] # [doc = " }) as Pin<Box<dyn Stream<Item = usize> + Send>>;"] # [doc = ""] # [doc = " let rx2 = Box::pin(async_stream::stream! {"] # [doc = "     while let Some(item) = rx2.recv().await {"] # [doc = "         yield item;"] # [doc = "     }"] # [doc = " }) as Pin<Box<dyn Stream<Item = usize> + Send>>;"] # [doc = ""] # [doc = " tokio::spawn(async move {"] # [doc = "     tx1.send(1).await.unwrap();"] # [doc = ""] # [doc = "     // This value will never be received. The send may or may not return"] # [doc = "     // `Err` depending on if the remote end closed first or not."] # [doc = "     let _ = tx1.send(2).await;"] # [doc = " });"] # [doc = ""] # [doc = " tokio::spawn(async move {"] # [doc = "     tx2.send(3).await.unwrap();"] # [doc = "     let _ = tx2.send(4).await;"] # [doc = " });"] # [doc = ""] # [doc = " let mut map = StreamMap::new();"] # [doc = ""] # [doc = " // Insert both streams"] # [doc = " map.insert(\"one\", rx1);"] # [doc = " map.insert(\"two\", rx2);"] # [doc = ""] # [doc = " // Read twice"] # [doc = " for _ in 0..2 {"] # [doc = "     let (key, val) = map.next().await.unwrap();"] # [doc = ""] # [doc = "     if key == \"one\" {"] # [doc = "         assert_eq!(val, 1);"] # [doc = "     } else {"] # [doc = "         assert_eq!(val, 3);"] # [doc = "     }"] # [doc = ""] # [doc = "     // Remove the stream to prevent reading the next value"] # [doc = "     map.remove(key);"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " This example models a read-only client to a chat system with channels. The"] # [doc = " client sends commands to join and leave channels. `StreamMap` is used to"] # [doc = " manage active channel subscriptions."] # [doc = ""] # [doc = " For simplicity, messages are displayed with `println!`, but they could be"] # [doc = " sent to the client over a socket."] # [doc = ""] # [doc = " ```no_run"] # [doc = " use tokio_stream::{Stream, StreamExt, StreamMap};"] # [doc = ""] # [doc = " enum Command {"] # [doc = "     Join(String),"] # [doc = "     Leave(String),"] # [doc = " }"] # [doc = ""] # [doc = " fn commands() -> impl Stream<Item = Command> {"] # [doc = "     // Streams in user commands by parsing `stdin`."] # [doc = " # tokio_stream::pending()"] # [doc = " }"] # [doc = ""] # [doc = " // Join a channel, returns a stream of messages received on the channel."] # [doc = " fn join(channel: &str) -> impl Stream<Item = String> + Unpin {"] # [doc = "     // left as an exercise to the reader"] # [doc = " # tokio_stream::pending()"] # [doc = " }"] # [doc = ""] # [doc = " #[tokio::main]"] # [doc = " async fn main() {"] # [doc = "     let mut channels = StreamMap::new();"] # [doc = ""] # [doc = "     // Input commands (join / leave channels)."] # [doc = "     let cmds = commands();"] # [doc = "     tokio::pin!(cmds);"] # [doc = ""] # [doc = "     loop {"] # [doc = "         tokio::select! {"] # [doc = "             Some(cmd) = cmds.next() => {"] # [doc = "                 match cmd {"] # [doc = "                     Command::Join(chan) => {"] # [doc = "                         // Join the channel and add it to the `channels`"] # [doc = "                         // stream map"] # [doc = "                         let msgs = join(&chan);"] # [doc = "                         channels.insert(chan, msgs);"] # [doc = "                     }"] # [doc = "                     Command::Leave(chan) => {"] # [doc = "                         channels.remove(&chan);"] # [doc = "                     }"] # [doc = "                 }"] # [doc = "             }"] # [doc = "             Some((chan, msg)) = channels.next() => {"] # [doc = "                 // Received a message, display it on stdout with the channel"] # [doc = "                 // it originated from."] # [doc = "                 println!(\"{}: {}\", chan, msg);"] # [doc = "             }"] # [doc = "             // Both the `commands` stream and the `channels` stream are"] # [doc = "             // complete. There is no more work to do, so leave the loop."] # [doc = "             else => break,"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Using `StreamNotifyClose` to handle closed streams with `StreamMap`."] # [doc = ""] # [doc = " ```"] # [doc = " use tokio_stream::{StreamExt, StreamMap, StreamNotifyClose};"] # [doc = ""] # [doc = " # #[tokio::main(flavor = \"current_thread\")]"] # [doc = " # async fn main() {"] # [doc = " let mut map = StreamMap::new();"] # [doc = " let stream = StreamNotifyClose::new(tokio_stream::iter(vec![0, 1]));"] # [doc = " let stream2 = StreamNotifyClose::new(tokio_stream::iter(vec![0, 1]));"] # [doc = " map.insert(0, stream);"] # [doc = " map.insert(1, stream2);"] # [doc = " while let Some((key, val)) = map.next().await {"] # [doc = "     match val {"] # [doc = "         Some(val) => println!(\"got {val:?} from stream {key:?}\"),"] # [doc = "         None => println!(\"stream {key:?} closed\"),"] # [doc = "     }"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [derive (Debug)] pub struct StreamMap < K , V > { # [doc = " Streams stored in the map"] entries : Vec < (K , V) > , }
    };
}

StreamMap!();